final class PageReviewer
{
    public function __construct(
        private readonly AgentRuntimeInterface $runtime,
    ) {}

    public function review(LlmConfiguration $configuration, int $beUserUid, bool $isAdmin): string
    {
        $request = new AgentRunRequest(
            configuration: $configuration,
            messages: [ChatMessage::user('Check the meta description of page 42.')],
            actor: AiActorContext::backendUser($beUserUid, $isAdmin),
            maxIterations: 10,
        );

        $result = $this->runtime->run($request);

        return match ($result->outcome) {
            AgentRunOutcome::COMPLETED => $result->loopResult?->finalContent ?? '',
            AgentRunOutcome::AWAITING_APPROVAL,
            AgentRunOutcome::AWAITING_INPUT => 'Waiting in the Agent Runs inbox: ' . $result->runUuid,
            default => 'Run ended: ' . $result->outcome->value,
        };
    }
}

